// Источник: web-тест .qa/e2e/tests/journey/jr-02-header-opens-profile.spec.ts, план .qa/e2e/specs/journey.md (14.4), кейс .qa/tests/journey/JR-02-avatar-name-open-profile.md
// Тикет #f6970bc6. Опора: ответ 28.09 (клик по аватару или имени → «פרופיל אישי»); a11y шапки «מעבר לפרטים שלי».
// URL `/profile` заменён проверкой экрана «פרופיל אישי».
import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, byLabel, tapText, expectVisibleText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

async function openJourney() {
  await goTab('המסע שלי');
  await (await byLabel('מעבר לפרטים שלי')).waitForDisplayed({ timeout: 20000 });
  const w = await byTextContains('עלית דרגה');
  if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
}

describe('«המסע שלי»', () => {
  afterEach(async () => { await toHome(); });

  it('JR-02 Клик по аватару или имени открывает «פרופיל אישי» #f6970bc6 @prod-safe', async () => {
    // 1. «המסע שלי» → имя «אקדא טסט».
    await openJourney();
    await expect(byLabel('מעבר לפרטים שלי')).toBeDisplayed();
    await tapText('אקדא טסט');
    await expectVisibleText('פרופיל אישי');

    // 2. Назад → аватар (буква «א»).
    await driver.back();
    await openJourney();
    await tapText('א');
    await expectVisibleText('פרופיל אישי');
    await expect(byText('מעבר לפרטים שלי')).not.toBeDisplayed();
  });
});
